// recipeHasPending — остались ли пороги, которые POST ещё создаст; когда все
// уже существуют, вместо кнопки — честное «все созданы» (повторный POST и так
// идемпотентен, но мёртвая кнопка хуже подписи).
func recipeHasPending(statuses []recipes.RuleStatus) bool {
	for _, st := range statuses {
		if !st.Exists {
			return true
		}
	}
	return false
}

